CREATE DATABASE IF NOT EXISTS `zhihu` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `zhihu`;

DROP TABLE IF EXISTS `t_special`;
CREATE TABLE `t_special` (
  `id`              VARCHAR(32)  NOT NULL                COMMENT '专题 id（知乎雪花 id，用字符串存）',
  `title`           VARCHAR(255) NOT NULL                COMMENT '专题标题',
  `introduction`    VARCHAR(1000)         DEFAULT NULL   COMMENT '专题简介',
  `banner`          VARCHAR(500)          DEFAULT NULL   COMMENT '头图地址',
  `view_count`      BIGINT                DEFAULT 0      COMMENT '浏览量',
  `followers_count` INT                   DEFAULT 0      COMMENT '关注量',
  `is_following`    TINYINT(1)            DEFAULT 0      COMMENT '是否已关注：1 是，0 否',
  `category`        VARCHAR(32)           DEFAULT NULL   COMMENT '分类（练习 1 新增：按关注量分档）',
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_followers` (`followers_count`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = '知乎专题表';

-- 分类阈值：关注量 >= 127 为「热门」，>= 39 为「关注中」，其余「小众」

